<?php declare(strict_types=1);session_start();require __DIR__.'/../config/config.local.php';if(!empty($_SESSION['somba_admin'])){header('Location:index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(hash_equals((string)config('admin.username','admin'),(string)($_POST['username']??''))&&password_verify((string)($_POST['password']??''),(string)config('admin.password_hash',''))){session_regenerate_id(true);$_SESSION['somba_admin']=true;$_SESSION['somba_admin_user']=(string)config('admin.username');header('Location:index.php');exit;}$error='Identifiants invalides';}?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SOMBA Admin</title><link rel="stylesheet" href="assets/admin.css"></head><body><main class="login"><h1>SOMBA Admin</h1><?php if($error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post"><input name="username" placeholder="Utilisateur" required><input name="password" type="password" placeholder="Mot de passe" required><button>Connexion</button></form><small>Configure username et password_hash dans config.local.php.</small></main></body></html>